import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Definizione di settore sferico","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/g_geometria-dello-spazio/gk/gkedda.md","filePath":"lezioni/g_geometria-dello-spazio/gk/gkedda.md"}`),a={name:`lezioni/g_geometria-dello-spazio/gk/gkedda.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="definizione-di-settore-sferico" tabindex="-1">Definizione di settore sferico <a class="header-anchor" href="#definizione-di-settore-sferico" aria-label="Permalink to “Definizione di settore sferico”">​</a></h1><p>Definiamo il settore sferico come solido di rotazione.</p><blockquote><p><strong>Definizione:</strong> Definiamo settore sferico la parte di spazio percorsa da un settore circolare quando compie una rotazione completa attorno ad un asse passante per il vertice e non avente altri punti comuni con il settore.</p></blockquote><p><a href="./gkeddaa.html">Vedere la costruzione</a></p><p>In pratica otteniamo un segmento sferico a due basi e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> coni che possono essere entrambi vuoti oppure uno solamente vuoto.</p><p>Nella prima figura vedi la zona sferica con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> buchi evidenziati in blu a forma di cono.</p><p>Nella seconda vedi invece la zona sferica con un buco a forma di cono più un altro cono. Questo dipende sia dalla misura dell&#39;angolo al centro del settore che dalla posizione dell&#39;asse di rotazione.</p><blockquote><p><strong>Osservazione:</strong> Evidenziamo ancora che, se l&#39;asse di rotazione coincide con un lato del settore circolare otteniamo un segmento sferico ad una base con un buco a forma di cono oppure, se tale settore ha angolo al centro superiore a <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>90</mn><mo>∘</mo></msup></mrow><annotation encoding="application/x-tex">90^\\circ</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6741em;"></span><span class="mord">9</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span></span></span></span>, con aggiunto un cono.</p></blockquote><p>Sulla sinistra un esempio con angolo al centro superiore ad un angolo retto, sulla destra, invece, con angolo inferiore.</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};